const raw = $input.first().json.data ?? $input.first().json.body ?? '';
const line = String(raw).split('\n').find((l) => l.startsWith('data:')) ?? '';
const rpc = JSON.parse(line.slice(5).trim());
const t = $('When Executed by Another Workflow').first().json;
// M6-P4e: the signed PRD's stack hint SELECTS the site kind. This vocabulary is the runtime twin of
// STACK_TO_FRAMEWORK (platform-nest provisioning.service.ts); a test pins the two together.
const KNOWN = ["a", "b", "c", "static", "vite", "astro", "wp", "wordpress", "fullstack", "full-stack", "node", "next", "nextjs"];
let stack = '', reason = '';
if (rpc.result?.isError) {
  reason = 'prd_unreadable: ' + (rpc.result.content?.[0]?.text || 'pipeline.getRun failed');
} else {
  let run = {}; try { run = JSON.parse(rpc.result?.content?.[0]?.text ?? '{}'); } catch { run = {}; }
  const prd = (run.stages || []).find((s) => s.name === 'prd_extract');
  const text = String(prd?.artifact_ref ?? '');
  // A `Stack: <hint>` line in the PRD text (markdown tolerant: **Stack:** C, - Stack: full-stack).
  const m = /^[ \t>*_#-]*(?:tech(?:nical)?[ -])?stack\b[^:=\n]{0,20}[:=][ \t*_`'"(]*([^\n]*)/im.exec(text);
  if (!m) {
    reason = 'prd_stack_missing: the signed PRD carries no "Stack:" line, so no site kind can be chosen (add one: static, wordpress or fullstack)';
  } else {
    const v = m[1].trim().toLowerCase();
    const two = /^([a-z0-9]+)[ -]([a-z0-9]+)/.exec(v);
    const one = /^[a-z0-9]+/.exec(v);
    const hit = [two ? two[1] + '-' + two[2] : '', one ? one[0] : ''].find((c) => c && KNOWN.includes(c));
    if (hit) stack = hit; else reason = 'unsupported_stack: the signed PRD stack hint "' + v.slice(0, 40) + '" is not one of ' + KNOWN.join('/');
  }
}
return [{ json: { tenantId: t.tenantId, runId: t.runId, stack, ok: stack !== '', reason } }];

const raw = $input.first().json.data ?? $input.first().json.body ?? '';
const line = String(raw).split('\n').find((l) => l.startsWith('data:')) ?? '';
const rpc = JSON.parse(line.slice(5).trim());
const t = $('When Executed by Another Workflow').first().json;
let suspended = false, failed = false, reason = '', site = null;
if (rpc.result?.isError) {
  reason = rpc.result.content?.[0]?.text || 'webdev.provisionSite failed';
  // Same shape pipeline-delivery.json's own 'Prod result' node already parses for deploy.production:
  // the D14 write gate's denial text is prefixed 'suspend: ...' -- design section 04's CONTRACT is that
  // this IS the success outcome for an automation-triggered provision (a human decides via WS4).
  suspended = /^suspend:/.test(reason);
  failed = !suspended;
} else {
  try { site = JSON.parse(rpc.result?.content?.[0]?.text ?? '{}'); } catch { site = null; }
}
return [{ json: { tenantId: t.tenantId, runId: t.runId, suspended, failed, reason, site } }];

const raw = $input.first().json.data ?? $input.first().json.body ?? '';
const line = String(raw).split('\n').find((l) => l.startsWith('data:')) ?? '';
const rpc = JSON.parse(line.slice(5).trim());
if (rpc.result?.isError) throw new Error(rpc.result.content?.[0]?.text ?? 'approvals.request failed');
let a = {}; try { a = JSON.parse(rpc.result?.content?.[0]?.text ?? '{}'); } catch {}
const p = $('Parse provision result').first().json;
return [{ json: { ok: true, action: 'provision_suspended', tenantId: p.tenantId, runId: p.runId, approvalId: a.id ?? null } }];
